def countWordPaths(board, word):
    m, n = len(board), len(board[0])
    codes = [ord(ch) - 96 for ch in word]
    L = len(codes)
    seen = [[False] * n for _ in range(m)]

    def go(r, c, k):
        if k == L - 1:
            return 1
        seen[r][c] = True
        total = 0
        want = codes[k + 1]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] == want and not seen[nr][nc]:
                total += go(nr, nc, k + 1)
        seen[r][c] = False
        return total

    total = 0
    for r in range(m):
        for c in range(n):
            if board[r][c] == codes[0]:
                total += go(r, c, 0)
    return total
